def reciprocal_rank_fusion(dense_ranks, sparse_ranks, k=60):
    rrf_scores = {}
    for rank, doc_id in enumerate(dense_ranks):
        rrf_scores[doc_id] = rrf_scores.get(doc_id, 0.0) + 1.0 / (k + rank + 1)
    for rank, doc_id in enumerate(sparse_ranks):
        rrf_scores[doc_id] = rrf_scores.get(doc_id, 0.0) + 1.0 / (k + rank + 1)
    # Sort by descending fused score
    return sorted(rrf_scores.items(), key=lambda x: x[1], reverse=True)

# Minimal GraphRAG Community Summarization
def graphrag_global_search(communities, query, llm_fn):
 intermediate_summaries = []
 for community in communities:
 context = community.render_text()
 summary = llm_fn(f"Answer '{query}' based on this community context:\n{context}")
 if summary.relevance_score > 0.5:
 intermediate_summaries.append(summary.text)
 # Hierarchical Reduce Step
 combined_context = "\n\n".join(intermediate_summaries)
 return llm_fn(f"Synthesize a final report for '{query}':\n{combined_context}")
